-- Sorts all 72,207 families into a status, using the working table only. This is the exact text I ran, and it processed about 15 MB.
CREATE OR REPLACE TABLE nokia_analytics.family_status AS WITH pubs AS (SELECT family_id, country_code, kind_code, filing_date, EXISTS(SELECT 1 FROM UNNEST(owners) AS o WHERE NOT REGEXP_CONTAINS(UPPER(o), r'TCL|OPTRONICS|KABEL|CABLE|FIBRES|MOBILE COMM|RADIOTELEPHONE|SUBMARCOM|SUBMARINE')) AS core_owner, country_code != 'WO' AND NOT STARTS_WITH(kind_code, 'S') AND (grant_date > 0 OR REGEXP_CONTAINS(kind_code, r'^[BCE]')) AS granted FROM nokia_analytics.portfolio_30y) SELECT family_id, LOGICAL_OR(core_owner) AS core_owner, LOGICAL_OR(granted) AS ever_granted, LOGICAL_OR(granted AND filing_date >= 20061101) AS granted_in_term, LOGICAL_OR(NOT granted AND country_code != 'WO' AND filing_date >= 20210101) AS recent_application, LOGICAL_OR(country_code = 'US' AND granted AND filing_date >= 20061101) AS us_in_term, COUNT(DISTINCT IF(granted AND filing_date >= 20061101, country_code, NULL)) AS offices_in_term, MIN(filing_date) AS first_filing, MAX(filing_date) AS last_filing FROM pubs GROUP BY family_id; SELECT CASE WHEN NOT core_owner THEN '5 Sold-business names only' WHEN granted_in_term THEN '1 Granted, within 20 years' WHEN recent_application THEN '2 Recent application, may be pending' WHEN ever_granted THEN '3 Granted, past 20 years' ELSE '4 Never granted, older filing' END AS status, COUNT(*) AS families, COUNTIF(us_in_term) AS with_us_in_term, ROUND(AVG(offices_in_term), 2) AS avg_offices_in_term FROM nokia_analytics.family_status GROUP BY status ORDER BY status;
